edits.with:
.nbmechip{display:inline-block;vertical-align:5px;margin-left:10px;font-family:var(--sans);font-size:9px;font-weight:800;letter-spacing:1px;color:#fff;background:#3F4A8A;padding:5px 9px;border-radius:var(--r-chip);box-shadow:var(--ec);white-space:nowrap}
/* NBME priority: a brief with any NBME-linked question shows one NBME badge instead of UWorld / Aquifer / Board.
   :has() rule for current browsers; .nbme-linked (set by the NBME script) for engines without :has().
   Kept as separate rules: an unsupported selector would void a shared selector list. */
.brief:has(li[data-nbme],.mcq[data-nbme]) > h4::after{content:"NBME" !important;display:inline-block;vertical-align:5px;margin-left:10px;font-family:var(--sans);font-size:9px;font-weight:800;letter-spacing:1px;color:#fff !important;background:#3F4A8A !important;padding:5px 9px;border-radius:var(--r-chip);box-shadow:var(--ec);white-space:nowrap}
.brief.nbme-linked > h4::after{content:"NBME" !important;display:inline-block;vertical-align:5px;margin-left:10px;font-family:var(--sans);font-size:9px;font-weight:800;letter-spacing:1px;color:#fff !important;background:#3F4A8A !important;padding:5px 9px;border-radius:var(--r-chip);box-shadow:var(--ec);white-space:nowrap}
.brief.nbme-linked > h4[data-nbme-n]::after{content:"NBME \00D7" attr(data-nbme-n) !important}

edits.find:
var old=h.querySelector('.nbmechip'); if(old) old.remove();
var n=nbmeIds(b).length; if(!n) return;
var c=document.createElement('span'); c.className='nbmechip'; c.textContent='NBME \u00d7'+n;
c.title='Linked to '+n+' NBME question'+(n>1?'s':''); h.appendChild(c);

edits.with:
var old=h.querySelector('.nbmechip'); if(old) old.remove();
/* one NBME badge on the title (CSS h4::after); the count shows only when above 1 */
var n=nbmeIds(b).length;
b.classList.toggle('nbme-linked',n>0);
if(n>1) h.setAttribute('data-nbme-n',String(n)); else h.removeAttribute('data-nbme-n');
